#include <iostream>
using namespace std;

template <typename T>
void swap2(T& a, T& b) {
    T t = a;
    a = b;
    b = t;
}

int main() {
    int x = {x};
    int y = {y};
    swap2(x, y);
    cout << x << " " << y << endl;
    return 0;
}
